 "content": "def transform(grid):
    """Mirror the non-background motif horizontally into the zero target block."""
    out = [row[:] for row in grid]
    bg = grid[0][0]
    # Find the bounding box of the motif (non-background cells), then mirror it.
    cells = [(r, c) for r, row in enumerate(grid) for c, v in enumerate(row) if v != bg and v != 0]
    if not cells:
        return out
    r0 = min(r for r, _ in cells)
    r1 = max(r for r, _ in cells)
    c0 = min(c for _, c in cells)
    c1 = max(c for _, c in cells)
    # Find the contiguous zero rectangle matching the motif's dimensions.
    h, w = r1 - r0 + 1, c1 - c0 + 1
    target = None
    for r in range(len(grid) - h + 1):
        for c in range(len(grid[0]) - w + 1):
            if all(grid[rr][cc] == 0 for rr in range(r, r + h) for cc in range(c, c + w)):
                target = (r, c)
                break
        if target:
            break
    if target is None:
        return out
    tr, tc = target
    for dr in range(h):
        for dc in range(w):
            out[tr + dr][tc + dc] = grid[r0 + dr][c1 - dc]
    return out
